use vstd::prelude::*;

verus! {

    /// Given a non‐empty array `a`, returns its maximum element.
    /// 
    /// Requires:
    ///   - a.len() > 0
    ///
    /// Ensures:
    ///   - The returned `max` is at least every element of `a`.
    ///   - There exists an index i s.t. a[i] == max.
    fn max_array(a: &Vec<i32>) -> i32
        requires
            a.len() > 0,
        ensures
            |res: i32| 
                // res is at least as large as every element
                forall(|j: usize| j < a.len() ==> res >= a[j])
                // res equals some element in the array
                && exists(|j: usize| j < a.len() && res == a[j])
    {
        // We initialize i = 1 and mx = a[0].
        let mut i: usize = 1;
        let mut mx: i32 = a[0];

        // Loop over the rest of the array maintaining that
        // mx is the maximum of a[0..i].
        while i < a.len() {
            invariant
                // i is always between 1 and a.len()
                i <= a.len();
            invariant
                // mx >= every element in the prefix a[0..i]
                forall(|j: usize| j < i ==> mx >= a[j]);
            invariant
                // mx is attained by some element in the prefix a[0..i]
                exists(|j: usize| j < i && mx == a[j]);
            decreases
                // we make progress because i increases each time
                a.len() - i;

            let v = a[i];
            if v > mx {
                mx = v;
            }
            i += 1;
        }

        // At loop exit, i == a.len(), so the invariants give us
        // that mx is the maximum over the entire array.
        mx
    }

}

